import{_ as a,o as n,a as p,b as l}from"./app.C41L12d5.js";const r=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"编程指南","link":"/guide/programming_guide/document_structure"},{"text":"高级编程","link":"/guide/programming_guide/advanced_programming/advanced_programming"},{"text":"Aclnn算子工程化开发","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/overview"},{"text":"设计与实现","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/design_and_implementation/operator_function_design"},{"text":"使用高阶API时配套的Tiling实现","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/design_and_implementation/tiling_with_advanced_api"}]},"headers":[],"relativePath":"guide/programming_guide/advanced_programming/aclnn_operator_development/design_and_implementation/tiling_with_advanced_api.md","filePath":"guide/programming_guide/advanced_programming/aclnn_operator_development/design_and_implementation/tiling_with_advanced_api.md","outlineHeaders":[{"level":2,"title":"高阶API Tiling的数据流","slug":"高阶API-Tiling的数据流","link":"#高阶API-Tiling的数据流"},{"level":2,"title":"定义包含TCubeTiling的TilingData","slug":"定义包含TCubeTiling的TilingData","link":"#定义包含TCubeTiling的TilingData"},{"level":2,"title":"在TilingFunc中调用配套Tiling类","slug":"在TilingFunc中调用配套Tiling类","link":"#在TilingFunc中调用配套Tiling类"},{"level":3,"title":"设置workspace","slug":"设置workspace","link":"#设置workspace"},{"level":3,"title":"校验输入条件","slug":"校验输入条件","link":"#校验输入条件"},{"level":2,"title":"核函数（Kernel）侧使用TCubeTiling","slug":"核函数（Kernel）侧使用TCubeTiling","link":"#核函数（Kernel）侧使用TCubeTiling"},{"level":2,"title":"相关文档","slug":"相关文档","link":"#相关文档"}],"lastUpdated":1787050286000}'),c={name:"guide/programming_guide/advanced_programming/aclnn_operator_development/design_and_implementation/tiling_with_advanced_api.md"};function e(i,s,t,o,g,w){return n(),p("div",null,[...s[0]||(s[0]=[l(`<div><article class="markdown-body"><h1>使用高阶API时配套的Tiling实现</h1><p>本文属于扩展内容，介绍使用高阶API时配套的Host侧Tiling实现。Matmul、Conv等高阶API通常提供配套的Host侧Tiling类，用于根据shape、dtype计算切分参数。开发者需要把配套Tiling类的计算结果传到核函数（Kernel）侧，并使用同一份数据初始化高阶API对象。</p><p>本文构造一个简化的aclnn工程化算子MatmulCustom作为示例。该算子只计算<code>C = A * B</code>，用于说明<code>MultiCoreMatmulTiling</code>和<code>TCubeTiling</code>在算子工程中的接入流程，不包含Bias、激活函数或多分支逻辑。</p><h2 id="高阶API-Tiling的数据流">高阶API Tiling的数据流<a class="header-anchor" href="#高阶API-Tiling的数据流">​</a></h2><p>配套流程如下：</p><div class="code-block"><pre class="highlight"><code>flowchart LR
    A[&quot;输入shape、dtype&quot;] --&gt; B[&quot;Host侧调用配套Tiling类计算切分参数&quot;]
    B --&gt; C[&quot;写入算子TilingData&quot;]
    C --&gt; D[&quot;传递到核函数（Kernel）侧&quot;]
    D --&gt; E[&quot;初始化高阶API对象并计算&quot;]
</code></pre></div><p>配套Tiling类负责计算高阶API内部使用的多核切分和核内切分参数，算子TilingData负责把计算结果传到核函数（Kernel）侧。</p><h2 id="定义包含TCubeTiling的TilingData">定义包含TCubeTiling的TilingData<a class="header-anchor" href="#定义包含TCubeTiling的TilingData">​</a></h2><p>高阶API的Tiling结构体可以通过标准C++方式或宏定义方式组织。本例为了展示<code>TILING_DATA_FIELD_DEF_STRUCT</code>的使用方法，选择宏定义方式嵌套<code>TCubeTiling</code>：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="cp">#ifndef MATMUL_CUSTOM_TILING_H</span>
<span class="cp">#define MATMUL_CUSTOM_TILING_H</span>
<span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;register/tilingdata_base.h&quot;</span>
<span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;tiling/tiling_api.h&quot;</span>

<span class="k">namespace</span><span class="w"> </span><span class="nn">optiling</span><span class="w"> </span><span class="p">{</span>
<span class="n">BEGIN_TILING_DATA_DEF</span><span class="p">(</span><span class="n">MatmulCustomTilingData</span><span class="p">)</span>
<span class="w">    </span><span class="n">TILING_DATA_FIELD_DEF_STRUCT</span><span class="p">(</span><span class="n">TCubeTiling</span><span class="p">,</span><span class="w"> </span><span class="n">cubeTilingData</span><span class="p">);</span>
<span class="n">END_TILING_DATA_DEF</span><span class="p">;</span>

<span class="n">REGISTER_TILING_DATA_CLASS</span><span class="p">(</span><span class="n">MatmulCustom</span><span class="p">,</span><span class="w"> </span><span class="n">MatmulCustomTilingData</span><span class="p">)</span>
<span class="p">}</span><span class="w"> </span><span class="c1">// namespace optiling</span>
<span class="cp">#endif </span><span class="c1">// MATMUL_CUSTOM_TILING_H</span>
</code></pre></div><p><code>TILING_DATA_FIELD_DEF_STRUCT</code>只能嵌套由同类宏定义的Tiling结构体，因此选择该宏时，外层<code>MatmulCustomTilingData</code>也需要使用宏定义方式。使用标准C++方式时，可以在普通结构体中直接声明<code>AscendC::tiling::TCubeTiling</code>字段，不使用上述宏。</p><p>宏定义方式会生成<code>SaveToBuffer()</code>和<code>GetDataSize()</code>等接口，Host侧计算完成后需要显式序列化TilingData。</p><h2 id="在TilingFunc中调用配套Tiling类">在TilingFunc中调用配套Tiling类<a class="header-anchor" href="#在TilingFunc中调用配套Tiling类">​</a></h2><p>本例固定A为<code>[512, 128]</code>、B为<code>[128, 512]</code>，输出C为<code>[512, 512]</code>。A、B使用<code>float16</code>，C使用<code>float</code>，矩阵均为ND格式。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;../op_kernel/matmul_custom_tiling.h&quot;</span>
<span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;register/op_def_registry.h&quot;</span>
<span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;tiling/tiling_api.h&quot;</span>

<span class="k">namespace</span><span class="w"> </span><span class="nn">optiling</span><span class="w"> </span><span class="p">{</span>
<span class="k">static</span><span class="w"> </span><span class="n">ge</span><span class="o">::</span><span class="n">graphStatus</span><span class="w"> </span><span class="nf">TilingFunc</span><span class="p">(</span><span class="n">gert</span><span class="o">::</span><span class="n">TilingContext</span><span class="o">*</span><span class="w"> </span><span class="n">context</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="k">constexpr</span><span class="w"> </span><span class="kt">int32_t</span><span class="w"> </span><span class="n">M</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">512</span><span class="p">;</span>
<span class="w">    </span><span class="k">constexpr</span><span class="w"> </span><span class="kt">int32_t</span><span class="w"> </span><span class="n">N</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">512</span><span class="p">;</span>
<span class="w">    </span><span class="k">constexpr</span><span class="w"> </span><span class="kt">int32_t</span><span class="w"> </span><span class="n">K</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">128</span><span class="p">;</span>
<span class="w">    </span><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">NUM_BLOCKS</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">2</span><span class="p">;</span>

<span class="w">    </span><span class="c1">// 使用当前芯片的平台信息初始化配套Tiling类。</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">platform</span><span class="w"> </span><span class="o">=</span>
<span class="w">        </span><span class="n">platform_ascendc</span><span class="o">::</span><span class="n">PlatformAscendC</span><span class="p">(</span><span class="n">context</span><span class="o">-&gt;</span><span class="n">GetPlatformInfo</span><span class="p">());</span>
<span class="w">    </span><span class="n">matmul_tiling</span><span class="o">::</span><span class="n">MultiCoreMatmulTiling</span><span class="w"> </span><span class="n">matmulTiling</span><span class="p">(</span><span class="n">platform</span><span class="p">);</span>

<span class="w">    </span><span class="c1">// 指定可使用的核数。A、B位于GM，使用ND格式和float16，</span>
<span class="w">    </span><span class="c1">// SetAType和SetBType的最后一个参数false表示矩阵不转置。</span>
<span class="w">    </span><span class="n">matmulTiling</span><span class="p">.</span><span class="n">SetDim</span><span class="p">(</span><span class="n">NUM_BLOCKS</span><span class="p">);</span>
<span class="w">    </span><span class="n">matmulTiling</span><span class="p">.</span><span class="n">SetAType</span><span class="p">(</span>
<span class="w">        </span><span class="n">matmul_tiling</span><span class="o">::</span><span class="n">TPosition</span><span class="o">::</span><span class="n">GM</span><span class="p">,</span>
<span class="w">        </span><span class="n">matmul_tiling</span><span class="o">::</span><span class="n">CubeFormat</span><span class="o">::</span><span class="n">ND</span><span class="p">,</span>
<span class="w">        </span><span class="n">matmul_tiling</span><span class="o">::</span><span class="n">DataType</span><span class="o">::</span><span class="n">DT_FLOAT16</span><span class="p">,</span>
<span class="w">        </span><span class="nb">false</span><span class="p">);</span>
<span class="w">    </span><span class="n">matmulTiling</span><span class="p">.</span><span class="n">SetBType</span><span class="p">(</span>
<span class="w">        </span><span class="n">matmul_tiling</span><span class="o">::</span><span class="n">TPosition</span><span class="o">::</span><span class="n">GM</span><span class="p">,</span>
<span class="w">        </span><span class="n">matmul_tiling</span><span class="o">::</span><span class="n">CubeFormat</span><span class="o">::</span><span class="n">ND</span><span class="p">,</span>
<span class="w">        </span><span class="n">matmul_tiling</span><span class="o">::</span><span class="n">DataType</span><span class="o">::</span><span class="n">DT_FLOAT16</span><span class="p">,</span>
<span class="w">        </span><span class="nb">false</span><span class="p">);</span>
<span class="w">    </span><span class="n">matmulTiling</span><span class="p">.</span><span class="n">SetCType</span><span class="p">(</span>
<span class="w">        </span><span class="n">matmul_tiling</span><span class="o">::</span><span class="n">TPosition</span><span class="o">::</span><span class="n">GM</span><span class="p">,</span>
<span class="w">        </span><span class="n">matmul_tiling</span><span class="o">::</span><span class="n">CubeFormat</span><span class="o">::</span><span class="n">ND</span><span class="p">,</span>
<span class="w">        </span><span class="n">matmul_tiling</span><span class="o">::</span><span class="n">DataType</span><span class="o">::</span><span class="n">DT_FLOAT</span><span class="p">);</span>
<span class="w">    </span><span class="c1">// 配置原始shape、本次计算shape、Bias开关和buffer空间。</span>
<span class="w">    </span><span class="n">matmulTiling</span><span class="p">.</span><span class="n">SetOrgShape</span><span class="p">(</span><span class="n">M</span><span class="p">,</span><span class="w"> </span><span class="n">N</span><span class="p">,</span><span class="w"> </span><span class="n">K</span><span class="p">);</span>
<span class="w">    </span><span class="n">matmulTiling</span><span class="p">.</span><span class="n">SetShape</span><span class="p">(</span><span class="n">M</span><span class="p">,</span><span class="w"> </span><span class="n">N</span><span class="p">,</span><span class="w"> </span><span class="n">K</span><span class="p">);</span>
<span class="w">    </span><span class="n">matmulTiling</span><span class="p">.</span><span class="n">EnableBias</span><span class="p">(</span><span class="nb">false</span><span class="p">);</span>
<span class="w">    </span><span class="n">matmulTiling</span><span class="p">.</span><span class="n">SetBufferSpace</span><span class="p">(</span><span class="mi">-1</span><span class="p">,</span><span class="w"> </span><span class="mi">-1</span><span class="p">,</span><span class="w"> </span><span class="mi">-1</span><span class="p">);</span>

<span class="w">    </span><span class="c1">// 计算Matmul高阶API所需的多核切分和核内切分参数。</span>
<span class="w">    </span><span class="n">MatmulCustomTilingData</span><span class="w"> </span><span class="n">tiling</span><span class="p">;</span>
<span class="w">    </span><span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">matmulTiling</span><span class="p">.</span><span class="n">GetTiling</span><span class="p">(</span><span class="n">tiling</span><span class="p">.</span><span class="n">cubeTilingData</span><span class="p">)</span><span class="w"> </span><span class="o">==</span><span class="w"> </span><span class="mi">-1</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="k">return</span><span class="w"> </span><span class="n">ge</span><span class="o">::</span><span class="n">GRAPH_FAILED</span><span class="p">;</span>
<span class="w">    </span><span class="p">}</span>
<span class="w">    </span><span class="kt">int32_t</span><span class="w"> </span><span class="n">usedCoreNum</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">tiling</span><span class="p">.</span><span class="n">cubeTilingData</span><span class="p">.</span><span class="n">get_usedCoreNum</span><span class="p">();</span>
<span class="w">    </span><span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">usedCoreNum</span><span class="w"> </span><span class="o">&lt;=</span><span class="w"> </span><span class="mi">0</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="k">return</span><span class="w"> </span><span class="n">ge</span><span class="o">::</span><span class="n">GRAPH_FAILED</span><span class="p">;</span>
<span class="w">    </span><span class="p">}</span>

<span class="w">    </span><span class="c1">// 将计算得到的TCubeTiling序列化到框架提供的TilingData buffer。</span>
<span class="w">    </span><span class="n">tiling</span><span class="p">.</span><span class="n">SaveToBuffer</span><span class="p">(</span><span class="n">context</span><span class="o">-&gt;</span><span class="n">GetRawTilingData</span><span class="p">()</span><span class="o">-&gt;</span><span class="n">GetData</span><span class="p">(),</span>
<span class="w">                        </span><span class="n">context</span><span class="o">-&gt;</span><span class="n">GetRawTilingData</span><span class="p">()</span><span class="o">-&gt;</span><span class="n">GetCapacity</span><span class="p">());</span>
<span class="w">    </span><span class="n">context</span><span class="o">-&gt;</span><span class="n">GetRawTilingData</span><span class="p">()</span><span class="o">-&gt;</span><span class="n">SetDataSize</span><span class="p">(</span><span class="n">tiling</span><span class="p">.</span><span class="n">GetDataSize</span><span class="p">());</span>

<span class="w">    </span><span class="c1">// 核函数（Kernel）启动核数需要与Tiling结果中的实际使用核数一致。</span>
<span class="w">    </span><span class="n">context</span><span class="o">-&gt;</span><span class="n">SetSimdNumBlocks</span><span class="p">(</span><span class="k">static_cast</span><span class="o">&lt;</span><span class="kt">uint32_t</span><span class="o">&gt;</span><span class="p">(</span><span class="n">usedCoreNum</span><span class="p">));</span>

<span class="w">    </span><span class="c1">// 系统workspace供高阶API内部计算使用，并与算子自定义workspace相加。</span>
<span class="w">    </span><span class="kt">size_t</span><span class="w"> </span><span class="n">userWorkspaceSize</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>
<span class="w">    </span><span class="kt">size_t</span><span class="w"> </span><span class="n">systemWorkspaceSize</span><span class="w"> </span><span class="o">=</span>
<span class="w">        </span><span class="k">static_cast</span><span class="o">&lt;</span><span class="kt">size_t</span><span class="o">&gt;</span><span class="p">(</span><span class="n">platform</span><span class="p">.</span><span class="n">GetLibApiWorkSpaceSize</span><span class="p">());</span>
<span class="w">    </span><span class="kt">size_t</span><span class="o">*</span><span class="w"> </span><span class="n">currentWorkspace</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">context</span><span class="o">-&gt;</span><span class="n">GetWorkspaceSizes</span><span class="p">(</span><span class="mi">1</span><span class="p">);</span>
<span class="w">    </span><span class="n">currentWorkspace</span><span class="p">[</span><span class="mi">0</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">systemWorkspaceSize</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">userWorkspaceSize</span><span class="p">;</span>
<span class="w">    </span><span class="k">return</span><span class="w"> </span><span class="n">ge</span><span class="o">::</span><span class="n">GRAPH_SUCCESS</span><span class="p">;</span>
<span class="p">}</span>
<span class="p">}</span><span class="w"> </span><span class="c1">// namespace optiling</span>
</code></pre></div><p>示例使用固定shape以突出配套Tiling类的接口。支持动态shape时，应从<code>TilingContext</code>读取<code>M</code>、<code>N</code>、<code>K</code>，并在调用<code>GetTiling</code>前校验rank、K维相等关系以及整数转换范围。</p><h3 id="设置workspace">设置workspace<a class="header-anchor" href="#设置workspace">​</a></h3><p>Matmul高阶API可能需要系统workspace。Host侧通过<code>GetLibApiWorkSpaceSize()</code>获取系统workspace大小，并与算子自定义workspace相加：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="kt">size_t</span><span class="w"> </span><span class="n">userWorkspaceSize</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>
<span class="kt">size_t</span><span class="w"> </span><span class="n">systemWorkspaceSize</span><span class="w"> </span><span class="o">=</span>
<span class="w">    </span><span class="k">static_cast</span><span class="o">&lt;</span><span class="kt">size_t</span><span class="o">&gt;</span><span class="p">(</span><span class="n">platform</span><span class="p">.</span><span class="n">GetLibApiWorkSpaceSize</span><span class="p">());</span>
<span class="kt">size_t</span><span class="o">*</span><span class="w"> </span><span class="n">currentWorkspace</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">context</span><span class="o">-&gt;</span><span class="n">GetWorkspaceSizes</span><span class="p">(</span><span class="mi">1</span><span class="p">);</span>
<span class="n">currentWorkspace</span><span class="p">[</span><span class="mi">0</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">systemWorkspaceSize</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">userWorkspaceSize</span><span class="p">;</span>
</code></pre></div><p>即使算子没有自定义临时数据，也需要检查高阶API是否使用系统workspace，不能直接把workspace设为0。</p><p>系统workspace和用户workspace的通用设置方法请参考<a href="../../../appendix/common_operations/how_to_use_workspace.html">如何使用workspace</a>。</p><h3 id="校验输入条件">校验输入条件<a class="header-anchor" href="#校验输入条件">​</a></h3><p>实际算子还需要在调用<code>GetTiling</code>前校验：</p><ul><li>A、B是否为二维矩阵。</li><li>A的K维与B的K维是否相等。</li><li>输入dtype和format是否与<code>SetAType</code>、<code>SetBType</code>配置一致。</li><li>输出shape、dtype和format是否与<code>SetCType</code>配置一致。</li><li><code>M</code>、<code>N</code>、<code>K</code>转换到<code>int32_t</code>前是否超出范围。</li></ul><p>校验失败时返回<code>ge::GRAPH_FAILED</code>，不要继续使用无效shape计算Tiling。</p><h2 id="核函数（Kernel）侧使用TCubeTiling">核函数（Kernel）侧使用TCubeTiling<a class="header-anchor" href="#核函数（Kernel）侧使用TCubeTiling">​</a></h2><p>核函数（Kernel）入口解析TilingData，并用其中的<code>TCubeTiling</code>注册Matmul对象：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;kernel_operator.h&quot;</span>
<span class="cp">#define ASCENDC_CUBE_ONLY</span>
<span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;lib/matmul_intf.h&quot;</span>

<span class="k">using</span><span class="w"> </span><span class="k">namespace</span><span class="w"> </span><span class="nn">matmul</span><span class="p">;</span>

<span class="k">extern</span><span class="w"> </span><span class="s">&quot;C&quot;</span><span class="w"> </span><span class="n">__global__</span><span class="w"> </span><span class="n">__aicore__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">matmul_custom</span><span class="p">(</span>
<span class="w">    </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">a</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">b</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">c</span><span class="p">,</span>
<span class="w">    </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">workspace</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">tiling</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">GET_TILING_DATA</span><span class="p">(</span><span class="n">tilingData</span><span class="p">,</span><span class="w"> </span><span class="n">tiling</span><span class="p">);</span>

<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">TPipe</span><span class="w"> </span><span class="n">pipe</span><span class="p">;</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">GlobalTensor</span><span class="o">&lt;</span><span class="n">half</span><span class="o">&gt;</span><span class="w"> </span><span class="n">aGlobal</span><span class="p">;</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">GlobalTensor</span><span class="o">&lt;</span><span class="n">half</span><span class="o">&gt;</span><span class="w"> </span><span class="n">bGlobal</span><span class="p">;</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">GlobalTensor</span><span class="o">&lt;</span><span class="kt">float</span><span class="o">&gt;</span><span class="w"> </span><span class="n">cGlobal</span><span class="p">;</span>
<span class="w">    </span><span class="n">aGlobal</span><span class="p">.</span><span class="n">SetGlobalBuffer</span><span class="p">(</span>
<span class="w">        </span><span class="k">reinterpret_cast</span><span class="o">&lt;</span><span class="n">__gm__</span><span class="w"> </span><span class="n">half</span><span class="o">*&gt;</span><span class="p">(</span><span class="n">a</span><span class="p">),</span>
<span class="w">        </span><span class="n">tilingData</span><span class="p">.</span><span class="n">cubeTilingData</span><span class="p">.</span><span class="n">M</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">tilingData</span><span class="p">.</span><span class="n">cubeTilingData</span><span class="p">.</span><span class="n">Ka</span><span class="p">);</span>
<span class="w">    </span><span class="n">bGlobal</span><span class="p">.</span><span class="n">SetGlobalBuffer</span><span class="p">(</span>
<span class="w">        </span><span class="k">reinterpret_cast</span><span class="o">&lt;</span><span class="n">__gm__</span><span class="w"> </span><span class="n">half</span><span class="o">*&gt;</span><span class="p">(</span><span class="n">b</span><span class="p">),</span>
<span class="w">        </span><span class="n">tilingData</span><span class="p">.</span><span class="n">cubeTilingData</span><span class="p">.</span><span class="n">Kb</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">tilingData</span><span class="p">.</span><span class="n">cubeTilingData</span><span class="p">.</span><span class="n">N</span><span class="p">);</span>
<span class="w">    </span><span class="n">cGlobal</span><span class="p">.</span><span class="n">SetGlobalBuffer</span><span class="p">(</span>
<span class="w">        </span><span class="k">reinterpret_cast</span><span class="o">&lt;</span><span class="n">__gm__</span><span class="w"> </span><span class="kt">float</span><span class="o">*&gt;</span><span class="p">(</span><span class="n">c</span><span class="p">),</span>
<span class="w">        </span><span class="n">tilingData</span><span class="p">.</span><span class="n">cubeTilingData</span><span class="p">.</span><span class="n">M</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">tilingData</span><span class="p">.</span><span class="n">cubeTilingData</span><span class="p">.</span><span class="n">N</span><span class="p">);</span>

<span class="w">    </span><span class="c1">// 模板参数中的位置、格式和数据类型需要与Host侧Tiling配置一致。</span>
<span class="w">    </span><span class="n">Matmul</span><span class="o">&lt;</span>
<span class="w">        </span><span class="n">MatmulType</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">TPosition</span><span class="o">::</span><span class="n">GM</span><span class="p">,</span><span class="w"> </span><span class="n">CubeFormat</span><span class="o">::</span><span class="n">ND</span><span class="p">,</span><span class="w"> </span><span class="n">half</span><span class="o">&gt;</span><span class="p">,</span>
<span class="w">        </span><span class="n">MatmulType</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">TPosition</span><span class="o">::</span><span class="n">GM</span><span class="p">,</span><span class="w"> </span><span class="n">CubeFormat</span><span class="o">::</span><span class="n">ND</span><span class="p">,</span><span class="w"> </span><span class="n">half</span><span class="o">&gt;</span><span class="p">,</span>
<span class="w">        </span><span class="n">MatmulType</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">TPosition</span><span class="o">::</span><span class="n">GM</span><span class="p">,</span><span class="w"> </span><span class="n">CubeFormat</span><span class="o">::</span><span class="n">ND</span><span class="p">,</span><span class="w"> </span><span class="kt">float</span><span class="o">&gt;&gt;</span><span class="w"> </span><span class="n">mm</span><span class="p">;</span>

<span class="w">    </span><span class="c1">// 使用系统workspace和TCubeTiling注册Matmul对象。</span>
<span class="w">    </span><span class="n">REGIST_MATMUL_OBJ</span><span class="p">(</span>
<span class="w">        </span><span class="o">&amp;</span><span class="n">pipe</span><span class="p">,</span><span class="w"> </span><span class="n">GetSysWorkSpacePtr</span><span class="p">(),</span><span class="w"> </span><span class="n">mm</span><span class="p">,</span>
<span class="w">        </span><span class="o">&amp;</span><span class="n">tilingData</span><span class="p">.</span><span class="n">cubeTilingData</span><span class="p">);</span>

<span class="w">    </span><span class="c1">// 设置原始矩阵的M、N、Ka和Kb。</span>
<span class="w">    </span><span class="n">mm</span><span class="p">.</span><span class="n">SetOrgShape</span><span class="p">(</span>
<span class="w">        </span><span class="n">tilingData</span><span class="p">.</span><span class="n">cubeTilingData</span><span class="p">.</span><span class="n">M</span><span class="p">,</span>
<span class="w">        </span><span class="n">tilingData</span><span class="p">.</span><span class="n">cubeTilingData</span><span class="p">.</span><span class="n">N</span><span class="p">,</span>
<span class="w">        </span><span class="n">tilingData</span><span class="p">.</span><span class="n">cubeTilingData</span><span class="p">.</span><span class="n">Ka</span><span class="p">,</span>
<span class="w">        </span><span class="n">tilingData</span><span class="p">.</span><span class="n">cubeTilingData</span><span class="p">.</span><span class="n">Kb</span><span class="p">);</span>

<span class="w">    </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">blockIdx</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="k">static_cast</span><span class="o">&lt;</span><span class="kt">uint64_t</span><span class="o">&gt;</span><span class="p">(</span><span class="n">AscendC</span><span class="o">::</span><span class="n">GetBlockIdx</span><span class="p">());</span>
<span class="w">    </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">aOffset</span><span class="w"> </span><span class="o">=</span>
<span class="w">        </span><span class="n">blockIdx</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">tilingData</span><span class="p">.</span><span class="n">cubeTilingData</span><span class="p">.</span><span class="n">singleCoreM</span><span class="w"> </span><span class="o">*</span>
<span class="w">        </span><span class="n">tilingData</span><span class="p">.</span><span class="n">cubeTilingData</span><span class="p">.</span><span class="n">Ka</span><span class="p">;</span>
<span class="w">    </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">cOffset</span><span class="w"> </span><span class="o">=</span>
<span class="w">        </span><span class="n">blockIdx</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">tilingData</span><span class="p">.</span><span class="n">cubeTilingData</span><span class="p">.</span><span class="n">singleCoreM</span><span class="w"> </span><span class="o">*</span>
<span class="w">        </span><span class="n">tilingData</span><span class="p">.</span><span class="n">cubeTilingData</span><span class="p">.</span><span class="n">N</span><span class="p">;</span>

<span class="w">    </span><span class="n">mm</span><span class="p">.</span><span class="n">SetTensorA</span><span class="p">(</span><span class="n">aGlobal</span><span class="p">[</span><span class="n">aOffset</span><span class="p">],</span><span class="w"> </span><span class="nb">false</span><span class="p">);</span>
<span class="w">    </span><span class="n">mm</span><span class="p">.</span><span class="n">SetTensorB</span><span class="p">(</span><span class="n">bGlobal</span><span class="p">[</span><span class="mi">0</span><span class="p">],</span><span class="w"> </span><span class="nb">false</span><span class="p">);</span>
<span class="w">    </span><span class="n">mm</span><span class="p">.</span><span class="n">IterateAll</span><span class="p">(</span><span class="n">cGlobal</span><span class="p">[</span><span class="n">cOffset</span><span class="p">]);</span>
<span class="w">    </span><span class="n">mm</span><span class="p">.</span><span class="n">End</span><span class="p">();</span>
<span class="p">}</span>
</code></pre></div><p>Host侧<code>SetAType</code>、<code>SetBType</code>和<code>SetCType</code>配置的位置、format、dtype，需要与核函数（Kernel）侧的<code>MatmulType</code>模板参数保持一致。本例按M轴分核：不同Block读取A的不同行，复用完整B矩阵，并把结果写入C的对应行。</p><h2 id="相关文档">相关文档<a class="header-anchor" href="#相关文档">​</a></h2><ul><li><a href="./host_tiling_implementation.html">Host侧Tiling实现</a>：普通TilingData和Tiling函数的基本流程。</li><li><a href="./kernel_operator_implementation.html">核函数（Kernel）侧算子实现</a>：核函数（Kernel）入口、TilingData解析和核函数（Kernel）编程流程。</li><li><a href="../../../../../api/SIMD-API/adv_api/cube_compute/Matmul_Tiling/Matmul_Tiling.html">Matmul-Tiling类</a>：配套Tiling类接口说明。</li></ul></article></div>`,1)])])}const u=a(c,[["render",e]]);export{r as __pageData,u as default};
